const staticData = $getWorkflowStaticData('global');
const bridgeOnline = (Date.now() - (staticData.lastBridgeHeartbeat || 0)) < 25000;
const initialState = {
  ok: true,
  bridgeOnline: bridgeOnline,
  lastBridgeHeartbeat: staticData.lastBridgeHeartbeat || 0,
  gcert: staticData.gcert || { valid: true, needsRenewal: false, label: '155h left', raw: 'LOAS2 valid' },
  workspaces: staticData.workspaces || [],
  conversations: staticData.conversations || [],
  commands: (staticData.commands || []).slice(0, 15)
};
