    .container { max-width: 720px; margin: 0 auto; padding: 14px 14px 14px 24px; }

    /* Section Labels & Badges */
    .section-label {
      font-size: 11px; font-weight: 700; text-transform: uppercase;
      letter-spacing: 0.08em; color: var(--muted); margin: 8px 0 8px 2px;
    }
