      animation: pulse 1.4s infinite;
    }
    @keyframes pulse {
      0%, 100% { opacity: 1; }
      50% { opacity: 0.55; }
    }

    /* Voice & Command Studio Card */
    .studio-card {
      background: var(--card); border: 1px solid var(--border);
      border-radius: 18px; padding: 14px 16px; margin-bottom: 18px;
