      border-left: 3px solid var(--primary); background: rgba(99, 102, 241, 0.08);
      padding: 8px 12px; border-radius: 0 8px 8px 0; margin: 10px 0; color: #cbd5e1;
    }
    .cider-md code.inline-code {
      background: rgba(148, 163, 184, 0.16); color: #e2e8f0;
      padding: 2px 6px; border-radius: 5px; font-size: 12.5px;
      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
    }
    .cider-file-chip {
      display: inline-flex; align-items: center; gap: 4px;
      background: rgba(56, 189, 248, 0.14); border: 1px solid rgba(56, 189, 248, 0.35);
      color: #38bdf8; padding: 1px 7px; border-radius: 6px; font-size: 12px;
      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
      text-decoration: none; font-weight: 600;
    }
    .cider-link {
      color: #60a5fa; text-decoration: underline; font-weight: 500;
    }
    .cider-code-wrap {
      background: #060911; border: 1px solid #1e293b; border-radius: 10px;
      margin: 10px 0; overflow: hidden;
    }
    .cider-code-bar {
      background: #0f172a; padding: 5px 10px; font-size: 11px; color: #94a3b8;
      display: flex; justify-content: space-between; align-items: center;
      border-bottom: 1px solid #1e293b;
      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
    }
    .cider-copy-btn {
      background: rgba(255,255,255,0.08); border: 1px solid #334155; color: #e2e8f0;
      padding: 2px 8px; border-radius: 5px; font-size: 10px; cursor: pointer;
    }
    .cider-code-pre {
      padding: 10px 12px; overflow-x: auto; font-size: 12px; line-height: 1.45;
      color: #e2e8f0; margin: 0;
      font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
    }
    .cider-table-wrap {
      overflow-x: auto; margin: 10px 0; border-radius: 10px; border: 1px solid var(--border);
    }
    .cider-table {
      width: 100%; border-collapse: collapse; font-size: 12.5px; text-align: left;
    }
    .cider-table th {
      background: #162038; color: #f8fafc; font-weight: 700; padding: 8px 10px;
      border-bottom: 1px solid var(--border);
    }
    .cider-table td {
      padding: 8px 10px; border-bottom: 1px solid rgba(38,51,84,0.5); color: #cbd5e1;
      vertical-align: top;
    }
    .cider-table tr:nth-child(even) td { background: rgba(255,255,255,0.02); }
  </style>
</head>
<body>

  <!-- PIN Lock Screen -->
  <div id="pinOverlay" style="display:none;">
    <div class="pin-card">
      <div style="font-size:42px; margin-bottom:10px;">🔒</div>
      <h2>Commander Locked</h2>
      <p>Enter your 6-digit PIN to unlock voice & workspace control for <b>sumantob.c.googlers.com</b></p>
      <input id="pinInput" type="password" inputmode="numeric" maxlength="6" class="pin-input" placeholder="082026" />
      <button class="btn btn-primary" type="button" onclick="unlockApp()">🔓 Unlock Commander</button>
      <div id="pinError" style="color:var(--rose); font-size:13px; margin-top:10px; display:none;">❌ Invalid PIN — enter 082026</div>
    </div>
  </div>

  <!-- CAREERPULSE + CIDER LEFT-EDGE PULL TAB (Supports Tap & Touch-Pull Gesture) -->
  <div id="leftEdgePullTab" class="left-edge-pull-tab"
       onclick="event.stopPropagation();setSliderState('open')"
       ontouchstart="handlePullTabTouchStart(event)"
       ontouchmove="handlePullTabTouchMove(event)"
       ontouchend="handlePullTabTouchEnd(event)"
       title="Pull out Workspaces &amp; Conversations">
    ▶ Workspaces &amp; Threads
  </div>

  <!-- CLICKABLE BACKDROP TO COLLAPSE SLIDER WHEN TAPPED OUTSIDE -->
  <div id="sliderBackdrop" class="slider-backdrop" onclick="setSliderState('closed')" title="Tap outside to close slider"></div>

  <!-- LEFT-TO-RIGHT SLIDER DRAWER (Cider Jetski Workspace & Conversation Tree) -->
  <div id="workspaceSlider" class="half-slider state-closed"
       ontouchstart="handleSliderTouchStart(event)"
       ontouchmove="handleSliderTouchMove(event)">
    <div class="slider-right-edge-grip" onclick="setSliderState('closed');event.stopPropagation();" title="Collapse Slider">
      ◀
    </div>
    <div class="slider-handle-bar">
      <div class="slider-title-row">
        <div style="display:flex; align-items:center; gap:8px;">
          <span style="font-size:16px;">🏄</span>
          <div>
            <div style="font-size:13.5px; font-weight:800; color:#f8fafc;">Workspaces &amp; Threads</div>
            <div style="font-size:10.5px; color:var(--muted);" id="sliderSubCount">Loading conversations...</div>
          </div>
        </div>
        <button type="button" class="slider-close-btn" onclick="setSliderState('closed')">◀ Hide</button>
      </div>
      <div class="slider-search-row">
        <input id="sliderSearchInput" type="text" class="slider-search-input" placeholder="🔍 Filter workspace or thread..." oninput="renderSliderContent()" />
        <button type="button" class="slider-new-btn" onclick="startNewConvInCurrentWs()">➕ New</button>
      </div>
    </div>

    <!-- Horizontal Workspace Filter Pills -->
    <div id="sliderWsChips" class="ws-chips-bar"></div>

    <!-- Scrollable Cider-Style Workspace & Conversation Tree -->
    <div id="sliderBodyContent" class="slider-body"></div>
  </div>

  <!-- Header: Remote Jetski + gcert Time + Lock/Unlock Toggle Button -->
  <header>
    <div class="header-top">
      <div class="brand">
        <button type="button" class="drawer-toggle-btn" onclick="toggleSlider()" title="Open Workspaces &amp; Conversations Slider">
          ☰
        </button>
        <div class="brand-title">
          <span>🏄 Remote Jetski</span>
          <span id="bridgeDot" class="dot dot-online" title="Workstation Online"></span>
        </div>
      </div>
      <div style="display:flex; align-items:center; gap:6px;">
        <button id="syncIconBtn" type="button" class="sync-icon-btn" onclick="refreshState()" title="Force Sync">🔄</button>
        <span id="gcertBadge" class="pill-badge pill-gcert-ok" onclick="enableAndTestGcertAlert()" title="Tap to test gcert notification">🔑 --</span>
        <button id="lockToggleBtn" type="button" class="pill-badge pill-unlocked" onclick="toggleLockState()">🔓 Lock</button>
      </div>
    </div>
  </header>

  <div class="container">
    <!-- Unlock Confirmation Toast -->
    <div id="unlockToast">✅ Commander Unlocked! You have full control of sumantob.c.googlers.com.</div>

    <!-- gcert Expiration Warning Banner -->
    <div id="gcertAlertBanner">
      🚨 <b>gcert Renewal Needed on Workstation!</b> Your Cloudtop LOAS2/gcert certificate has expired or is under 1 hour remaining. Run <code>gcert</code> on your workstation for Google corp/CitC access.
    </div>

    <!-- Studio Card: Active Thread Banner (Opens Slider) + Voice + Execute -->
    <div class="studio-card">
      <!-- Clickable Active Conversation Bar (Opens Left Slider like Cider/CareerPulse) -->
      <div class="target-banner" onclick="setSliderState('open')" title="Tap to switch Workspace or Conversation">
        <div class="target-banner-left">
          <span class="target-drawer-pill">📁 Switch ▾</span>
          <div style="min-width:0; flex:1;">
            <div class="target-name" id="targetTitle">Select a conversation</div>
            <div class="target-ws" id="targetSub">Workspace: —</div>
          </div>
        </div>
        <span id="targetStatusBadge" class="status-badge status-IDLE">IDLE</span>
      </div>

      <!-- Active Running Banner + Cancel/Stop Button -->
      <div id="runningAlert" class="running-alert">
        <div class="running-step" id="runningStepText">⚡ Agent is currently executing a turn in this conversation...</div>
        <button class="btn btn-rose" type="button" onclick="cancelActiveConversation()">🛑 Stop / Cancel Execution</button>
      </div>

      <!-- Two Voice Capture Options -->
      <div class="section-label" style="margin-top:0;">Speak Command (Populates Review Box Below)</div>
      <div class="mic-row">
        <button id="liveMicBtn" type="button" class="mic-btn" onclick="toggleLiveSpeech()">
          <span class="icon">🎙️</span>
          <span>Live Android Mic</span>
          <span class="sub">Instant Browser Speech</span>
        </button>
        <button id="whisperMicBtn" type="button" class="mic-btn" onclick="toggleWhisperRecording()">
          <span class="icon">🎧</span>
          <span id="whisperBtnLabel">Whisper AI Mic</span>
          <span class="sub">Local 64-Core Whisper</span>
        </button>
      </div>

      <div class="voice-status">
        <span id="voiceStatusText">Ready — Speak or type below. Nothing sends until you tap Send.</span>
        <button type="button" onclick="clearPrompt()" style="background:none; border:none; color:var(--muted); font-size:12px; cursor:pointer;">Clear ✕</button>
      </div>

      <!-- Editable Textarea before sending -->
      <textarea id="promptBox" class="prompt-box" placeholder="Your transcribed voice command will appear here so you can read and edit it before sending to the workspace..."></textarea>

      <div class="action-row">
        <button id="sendBtn" type="button" class="btn btn-emerald" onclick="sendCommandToWorkspace()">
          Send
        </button>
      </div>
    </div>

    <!-- Live Conversation Reply & Recent Messages -->
    <div class="section-label">Live Status &amp; Cider Conversation Replies</div>
    <div id="queueStatusBox" style="margin-bottom:10px;"></div>
    <div id="chatHistory" class="chat-box"></div>
  </div>

<script>
window.__INITIAL_STATE__ = __SSR_INITIAL_STATE_JSON__;

const API_URL = window.location.origin && window.location.origin !== "null"
  ? window.location.origin + "/webhook/jetski-remote-api"
  : "http://localhost:11434/webhook/jetski-remote-api";

function safeGetStorage(k) {
  try { return window.localStorage.getItem(k) || ""; } catch (e) { return ""; }
}

function safeSetStorage(k, v) {
  try {
    if (v) window.localStorage.setItem(k, v);
    else window.localStorage.removeItem(k);
  } catch (e) {}
}

let userPin = safeGetStorage("jetski_remote_pin");
let appState = window.__INITIAL_STATE__ || { workspaces: [], conversations: [], commands: [], bridgeOnline: true };
let selectedWorkspace = "ALL";
let selectedConvId = null;
let sliderState = "closed";
let collapsedWorkspaces = {};
let lastGcertNotified = 0;

// Speech Recognition & Whisper MediaRecorder state
let recognition = null;
let isLiveRecording = false;
let mediaRecorder = null;
let audioChunks = [];
let isWhisperRecording = false;

function initLockState() {
  const lockBtn = document.getElementById("lockToggleBtn");
  if (userPin === "082026") {
    document.getElementById("pinOverlay").style.display = "none";
    if (lockBtn) {
      lockBtn.className = "pill-badge pill-unlocked";
      lockBtn.textContent = "🔓 Lock";
    }
  } else {
    document.getElementById("pinOverlay").style.display = "flex";
    if (lockBtn) {
      lockBtn.className = "pill-badge pill-locked";
      lockBtn.textContent = "🔒 Unlock";
    }
  }
}

function toggleLockState() {
  if (userPin === "082026") {
    lockApp();
  } else {
    const pinInput = document.getElementById("pinInput");
    if (pinInput && pinInput.value.trim() === "082026") {
      unlockApp();
    } else {
      document.getElementById("pinOverlay").style.display = "flex";
      if (pinInput) pinInput.focus();
    }
  }
}

// ============================================================================
// CAREERPULSE + CIDER SLIDER STATE & TOUCH GESTURES
// ============================================================================
function setSliderState(newState) {
  sliderState = newState === "open" ? "open" : "closed";
  const sliderEl = document.getElementById("workspaceSlider");
  const backdropEl = document.getElementById("sliderBackdrop");
  const pullTabEl = document.getElementById("leftEdgePullTab");

  if (sliderEl) {
    sliderEl.className = "half-slider state-" + sliderState;
  }
  if (backdropEl) {
    backdropEl.classList.toggle("open", sliderState === "open");
  }
  if (pullTabEl) {
    pullTabEl.style.display = sliderState === "closed" ? "flex" : "none";
  }
  if (sliderState === "open") {
    renderSliderContent();
  }
}

function toggleSlider() {
  setSliderState(sliderState === "open" ? "closed" : "open");
}

function handlePullTabTouchStart(e) {
  if (e) e.stopPropagation();
  window._pullTabStartX = (e.touches && e.touches[0]) ? e.touches[0].clientX : 0;
}

function handlePullTabTouchMove(e) {
  if (e) e.stopPropagation();
  const cx = (e.touches && e.touches[0]) ? e.touches[0].clientX : 0;
  if (cx - (window._pullTabStartX || 0) > 8 && sliderState === "closed") {
    setSliderState("open");
  }
}

function handlePullTabTouchEnd(e) {
  if (e) {
    e.stopPropagation();
    if (e.cancelable) e.preventDefault();
  }
  if (sliderState === "closed") {
    setSliderState("open");
  }
}

function handleSliderTouchStart(e) {
  window._sliderTouchStartX = (e.touches && e.touches[0]) ? e.touches[0].clientX : null;
  window._sliderTouchStartY = (e.touches && e.touches[0]) ? e.touches[0].clientY : null;
}

function handleSliderTouchMove(e) {
  if (window._sliderTouchStartX === null || sliderState !== "open") return;
  const cx = (e.touches && e.touches[0]) ? e.touches[0].clientX : 0;
  const cy = (e.touches && e.touches[0]) ? e.touches[0].clientY : 0;
  const dx = cx - window._sliderTouchStartX;
  const dy = Math.abs(cy - (window._sliderTouchStartY || 0));
  // Swipe left to close slider
  if (dx < -45 && dy < 35) {
    window._sliderTouchStartX = null;
    setSliderState("closed");
  }
}

function renderAll() {
  ensureDefaultSelection();
  renderHeader();
  renderGcertStatus();
  renderSliderContent();
  renderSelectedStudio();
  renderCommandFeed();
}

function ensureDefaultSelection() {
  const allConvs = appState.conversations || [];
  if (!selectedConvId && allConvs.length > 0) {
    selectedConvId = allConvs[0].id;
  }
}

async function unlockApp() {
  const val = document.getElementById("pinInput").value.trim();
  if (val !== "082026") {
    document.getElementById("pinError").style.display = "block";
    return;
  }
  userPin = val;
  safeSetStorage("jetski_remote_pin", userPin);
  document.getElementById("pinOverlay").style.display = "none";
  document.getElementById("pinError").style.display = "none";
  initLockState();

  const toast = document.getElementById("unlockToast");
  toast.style.display = "block";
  setTimeout(function() { toast.style.display = "none"; }, 5000);

  await refreshState(true);
}

function lockApp() {
  safeSetStorage("jetski_remote_pin", "");
  userPin = "";
  document.getElementById("pinInput").value = "";
  initLockState();
}

async function apiCall(payload) {
  const res = await fetch(API_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(Object.assign({}, payload, { pin: userPin || "082026" }))
  });
  return await res.json();
}

async function refreshState(isLoginCheck) {
  try {
    const data = await apiCall({ action: "get_state" });
    if (!data || data.error === "UNAUTHORIZED") {
      if (!isLoginCheck) lockApp();
      return false;
    }
    appState = data;
    renderAll();
    return true;
  } catch (err) {
    console.warn("Sync notice:", err);
    return false;
  }
}

function renderHeader() {
  const dot = document.getElementById("bridgeDot");
  if (!dot) return;
  if (appState.bridgeOnline) {
    dot.className = "dot dot-online";
  } else {
    dot.className = "dot dot-offline";
  }
}

function renderGcertStatus() {
  const badge = document.getElementById("gcertBadge");
  const banner = document.getElementById("gcertAlertBanner");
  const gcert = appState.gcert || { valid: true, needsRenewal: false, label: "155h left" };

  if (gcert.needsRenewal || !gcert.valid) {
    badge.className = "pill-badge pill-gcert-warn";
    badge.textContent = "🚨 gcert: " + (gcert.label || "EXPIRED");
    banner.style.display = "block";
    if (Date.now() - lastGcertNotified > 1800000) {
      lastGcertNotified = Date.now();
      triggerPhoneNotification("🚨 Cloudtop gcert Required!", "Your workstation gcert certificate needs renewal. Please run gcert on sumantob.c.googlers.com.");
    }
  } else {
    badge.className = "pill-badge pill-gcert-ok";
    badge.textContent = "🔑 " + (gcert.label || "Active");
    banner.style.display = "none";
  }
}

function triggerPhoneNotification(title, bodyText) {
  try {
    if (navigator.vibrate) navigator.vibrate([250, 100, 250]);
    if ("Notification" in window && Notification.permission === "granted") {
      new Notification(title, { body: bodyText });
    }
  } catch (e) {}
}

async function enableAndTestGcertAlert() {
  const gcert = appState.gcert || { label: "155h left" };
  try {
    if ("Notification" in window && Notification.permission !== "granted") {
      await Notification.requestPermission();
    }
  } catch (e) {}
  triggerPhoneNotification("🔑 Jetski gcert Monitor Active", "Current Cloudtop status: " + (gcert.raw || gcert.label) + ". You will be alerted when renewal is needed!");
  const statusEl = document.getElementById("voiceStatusText");
  statusEl.textContent = "🔔 gcert Alert Tested! Status: " + (gcert.raw || gcert.label);
}

// ============================================================================
// RENDER SLIDER CONTENT (Workspaces Chips + Cider Grouped Conversation Tree)
// ============================================================================
function renderSliderContent() {
  const chipsEl = document.getElementById("sliderWsChips");
  const bodyEl = document.getElementById("sliderBodyContent");
  const subCountEl = document.getElementById("sliderSubCount");
  const searchInput = document.getElementById("sliderSearchInput");
  if (!chipsEl || !bodyEl) return;

  const query = searchInput ? searchInput.value.trim().toLowerCase() : "";
  const convs = appState.conversations || [];
  const wsList = appState.workspaces || [];

  const counts = { ALL: convs.length };
  for (let i = 0; i < convs.length; i++) {
    const w = convs[i].workspace || "General";
    counts[w] = (counts[w] || 0) + 1;
  }

  if (subCountEl) {
    subCountEl.textContent = wsList.length + " workspaces • " + convs.length + " conversations";
  }

  const allTabs = ["ALL"].concat(wsList);
  chipsEl.innerHTML = allTabs.map(function(w) {
    const activeClass = selectedWorkspace === w ? " active" : "";
    const label = w === "ALL" ? "🌐 All" : "📁 " + w;
    const cnt = counts[w] || 0;
    return '<button type="button" class="ws-chip' + activeClass + '" onclick="selectWorkspaceFilter(\'' + escapeHtml(w) + '\')">' +
      '<span>' + escapeHtml(label) + '</span>' +
      '<span class="ws-chip-count">' + cnt + '</span>' +
    '</button>';
  }).join("");

  // Group conversations by workspace (like Cider's Jetski sidebar)
  const targetWorkspaces = selectedWorkspace === "ALL" ? wsList : [selectedWorkspace];
  let groupsHtml = "";

  for (let wIdx = 0; wIdx < targetWorkspaces.length; wIdx++) {
    const wsName = targetWorkspaces[wIdx];
    const wsConvs = convs.filter(function(c) {
      if ((c.workspace || "General") !== wsName) return false;
      if (!query) return true;
      const t = (c.title || "").toLowerCase();
      const w = (c.workspace || "").toLowerCase();
      return t.indexOf(query) !== -1 || w.indexOf(query) !== -1;
    });

    if (query && wsConvs.length === 0) continue;

    const isCollapsed = !!collapsedWorkspaces[wsName] && !query;
    const chevron = isCollapsed ? "▸" : "▾";

    let itemsHtml = "";
    if (!isCollapsed) {
      itemsHtml = '<div class="ws-group-list">';
      for (let cIdx = 0; cIdx < wsConvs.length; cIdx++) {
        const c = wsConvs[cIdx];
        const isSelected = c.id === selectedConvId;
        const isRun = c.status === "RUNNING";
        const badgeHtml = isRun
          ? '<span class="status-badge status-RUNNING" style="font-size:9.5px; padding:2px 7px;">⚡ RUN</span>'
          : '<span style="color:#34d399; font-size:10px; font-weight:700;">●</span>';

        itemsHtml += '<div class="slider-conv-item' + (isSelected ? ' active' : '') + '" onclick="pickConversationFromSlider(\'' + escapeHtml(c.id) + '\')">' +
          '<div class="slider-conv-main">' +
            '<div class="slider-conv-title">' + escapeHtml(c.title || "Untitled Conversation") + '</div>' +
            '<div class="slider-conv-meta">' +
              '<span>📁 ' + escapeHtml(c.workspace || "General") + '</span>' +
              (c.updatedAgo ? '<span>• ' + escapeHtml(c.updatedAgo) + '</span>' : '') +
            '</div>' +
          '</div>' +
          badgeHtml +
        '</div>';
      }

      // Add a "+ Start new thread in <wsName>" row inside each workspace group
      const newId = "NEW:" + wsName;
      const isNewSelected = selectedConvId === newId;
      itemsHtml += '<div class="slider-conv-item' + (isNewSelected ? ' active' : '') + '" onclick="pickConversationFromSlider(\'' + escapeHtml(newId) + '\')">' +
        '<div class="slider-conv-main">' +
          '<div class="slider-conv-title" style="color:#a5b4fc;">➕ Start New Conversation in "' + escapeHtml(wsName) + '"</div>' +
        '</div>' +
      '</div>';
      itemsHtml += '</div>';
    }

    groupsHtml += '<div class="ws-group">' +
      '<div class="ws-group-header" onclick="toggleWorkspaceCollapse(\'' + escapeHtml(wsName) + '\')">' +
        '<div class="ws-group-title">' +
          '<span>' + chevron + '</span>' +
          '<span>📁 ' + escapeHtml(wsName) + '</span>' +
          '<span style="font-size:10.5px; color:var(--muted); font-weight:600;">(' + wsConvs.length + ')</span>' +
        '</div>' +
        '<div class="ws-group-actions">' +
          '<button type="button" class="ws-mini-new-btn" onclick="event.stopPropagation();pickConversationFromSlider(\'NEW:' + escapeHtml(wsName) + '\')">+ New</button>' +
        '</div>' +
      '</div>' +
      itemsHtml +
    '</div>';
  }

  if (!groupsHtml) {
    groupsHtml = '<div style="text-align:center; color:var(--muted); padding:24px 12px; font-size:13px;">No matching conversations found.</div>';
  }

  bodyEl.innerHTML = groupsHtml;
}

function selectWorkspaceFilter(ws) {
  selectedWorkspace = ws || "ALL";
  renderSliderContent();
}

function toggleWorkspaceCollapse(wsName) {
  collapsedWorkspaces[wsName] = !collapsedWorkspaces[wsName];
  renderSliderContent();
}

function startNewConvInCurrentWs() {
  const targetWs = selectedWorkspace === "ALL" ? "n8n" : selectedWorkspace;
  pickConversationFromSlider("NEW:" + targetWs);
}

function pickConversationFromSlider(convId) {
  selectedConvId = convId;
  setSliderState("closed");
  renderSelectedStudio();
  renderSliderContent();
}

function getSelectedConvObject() {
  if (!selectedConvId) return null;
  if (selectedConvId.indexOf("NEW:") === 0) {
    const ws = selectedConvId.split(":")[1] || "General";
    return {
      id: selectedConvId,
      title: "New Conversation (" + ws + ")",
      workspace: ws,
      status: "IDLE",
      isNew: true,
      recentMessages: []
    };
  }
  const convs = appState.conversations || [];
  for (let i = 0; i < convs.length; i++) {
    if (convs[i].id === selectedConvId) return convs[i];
  }
  return null;
}

function renderSelectedStudio() {
  const conv = getSelectedConvObject();
  const titleEl = document.getElementById("targetTitle");
  const subEl = document.getElementById("targetSub");
  const badgeEl = document.getElementById("targetStatusBadge");
  const runAlert = document.getElementById("runningAlert");
  const runStep = document.getElementById("runningStepText");
  const sendBtn = document.getElementById("sendBtn");
  const chatEl = document.getElementById("chatHistory");

  if (!conv) {
    titleEl.textContent = "Tap here or slide from left to choose a thread";
    subEl.textContent = "Workspace: —";
    return;
  }

  titleEl.textContent = conv.title;
  subEl.textContent = "📁 " + conv.workspace + (conv.isNew ? " • Creates new thread" : (conv.updatedAgo ? " • Updated " + conv.updatedAgo : " • ID: " + conv.id.slice(0, 8)));
  const isRun = conv.status === "RUNNING";
  badgeEl.className = "status-badge status-" + (isRun ? "RUNNING" : "IDLE");
  badgeEl.textContent = isRun ? "⚡ RUNNING" : "🟢 IDLE";

  if (isRun) {
    runAlert.classList.add("show");
    runStep.textContent = conv.activeStep || "⚡ Agent is actively executing in this conversation...";
  } else {
    runAlert.classList.remove("show");
  }

  sendBtn.textContent = "Send";

  const msgs = conv.recentMessages || [];
  if (msgs.length === 0) {
