function copyCodeBlock(btn) {
  const pre = btn.parentElement.nextElementSibling;
  if (!pre) return;
  try {
    navigator.clipboard.writeText(pre.textContent || "");
    btn.textContent = "✅ Copied";
    setTimeout(function() { btn.textContent = "📋 Copy"; }, 1800);
  } catch (e) {}
}

function formatInlineMarkdown(line) {
  let s = escapeHtml(line);
  // Inline code `...`
  s = s.replace(/`([^`]+)`/g, '<code class="inline-code">$1</code>');
  // Markdown links [text](url)
  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, function(_, label, url) {
    if (url.indexOf("file://") === 0) {
      return '<span class="cider-file-chip">📄 ' + label + '</span>';
    }
    return '<a class="cider-link" href="' + url + '" target="_blank" rel="noopener">' + label + '</a>';
  });
  // Bold **...**
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  // Italic *...*
  s = s.replace(/(^|[^*])\*([^*]+)\*/g, '$1<em>$2</em>');
  return s;
}

function renderCiderMarkdown(md) {
  if (!md) return "";
  // Extract fenced code blocks first
  const codeBlocks = [];
  const textWithPlaceholders = String(md).replace(/```([a-zA-Z0-9_-]*)\n([\s\S]*?)```/g, function(_, lang, code) {
    const idx = codeBlocks.length;
    const langLabel = lang || "code";
    codeBlocks.push(
      '<div class="cider-code-wrap">' +
        '<div class="cider-code-bar"><span>' + escapeHtml(langLabel) + '</span><button type="button" class="cider-copy-btn" onclick="copyCodeBlock(this)">📋 Copy</button></div>' +
        '<pre class="cider-code-pre">' + escapeHtml(code.replace(/\n$/, "")) + '</pre>' +
      '</div>'
    );
    return "\n@@CODEBLOCK_" + idx + "@@\n";
  });

  const lines = textWithPlaceholders.split("\n");
  const out = [];
  let inList = false;
  let listType = "ul";
  let tableRows = [];

  function flushList() {
    if (inList) {
      out.push("</" + listType + ">");
      inList = false;
    }
  }

  function flushTable() {
    if (tableRows.length === 0) return;
    let html = '<div class="cider-table-wrap"><table class="cider-table">';
    for (let r = 0; r < tableRows.length; r++) {
      const rawRow = tableRows[r].trim().replace(/^\||\|$/g, "");
      const cells = rawRow.split("|").map(function(c) { return c.trim(); });
      if (r === 1 && cells.every(function(c) { return /^:?-{2,}:?$/.test(c); })) {
        continue;
      }
      const tag = r === 0 ? "th" : "td";
      html += "<tr>" + cells.map(function(c) { return "<" + tag + ">" + formatInlineMarkdown(c) + "</" + tag + ">"; }).join("") + "</tr>";
    }
    html += "</table></div>";
    out.push(html);
    tableRows = [];
  }

  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    const trimmed = raw.trim();

    if (/^@@CODEBLOCK_\d+@@$/.test(trimmed)) {
      flushList();
      flushTable();
      const idx = parseInt(trimmed.replace("@@CODEBLOCK_", "").replace("@@", ""), 10);
      out.push(codeBlocks[idx] || "");
      continue;
    }

    if (trimmed.indexOf("|") === 0 && trimmed.lastIndexOf("|") > 0) {
      flushList();
      tableRows.push(trimmed);
      continue;
    } else {
      flushTable();
    }

    if (!trimmed) {
      flushList();
      continue;
    }

    if (/^---+$/.test(trimmed) || /^\*\*\*+$/.test(trimmed)) {
      flushList();
      out.push("<hr/>");
      continue;
    }

    if (trimmed.indexOf("#### ") === 0) {
      flushList();
      out.push("<h4>" + formatInlineMarkdown(trimmed.slice(5)) + "</h4>");
      continue;
    }
    if (trimmed.indexOf("### ") === 0) {
      flushList();
      out.push("<h3>" + formatInlineMarkdown(trimmed.slice(4)) + "</h3>");
      continue;
    }
    if (trimmed.indexOf("## ") === 0) {
      flushList();
      out.push("<h2>" + formatInlineMarkdown(trimmed.slice(3)) + "</h2>");
      continue;
    }
    if (trimmed.indexOf("# ") === 0) {
      flushList();
      out.push("<h1>" + formatInlineMarkdown(trimmed.slice(2)) + "</h1>");
      continue;
    }

    if (trimmed.indexOf("> ") === 0) {
      flushList();
      out.push("<blockquote>" + formatInlineMarkdown(trimmed.slice(2)) + "</blockquote>");
      continue;
    }

    const ulMatch = trimmed.match(/^[-*•]\s+(.*)$/);
    if (ulMatch) {
      if (!inList || listType !== "ul") {
        flushList();
        inList = true;
        listType = "ul";
        out.push("<ul>");
      }
      out.push("<li>" + formatInlineMarkdown(ulMatch[1]) + "</li>");
      continue;
    }

    const olMatch = trimmed.match(/^\d+\.\s+(.*)$/);
    if (olMatch) {
      if (!inList || listType !== "ol") {
        flushList();
        inList = true;
        listType = "ol";
        out.push("<ol>");
      }
      out.push("<li>" + formatInlineMarkdown(olMatch[1]) + "</li>");
      continue;
    }

    flushList();
    out.push("<p>" + formatInlineMarkdown(trimmed) + "</p>");
  }

  flushList();
  flushTable();
  return out.join("");
}

