function toggleLiveSpeech() {
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  const btn = document.getElementById("liveMicBtn");
  const statusEl = document.getElementById("voiceStatusText");
  const box = document.getElementById("promptBox");

  if (!SpeechRecognition) {
    statusEl.textContent = "⚠️ Browser speech API unavailable here — tap the Whisper AI Mic button instead!";
    return;
  }

  if (isLiveRecording && recognition) {
    recognition.stop();
    return;
  }

  recognition = new SpeechRecognition();
  recognition.lang = "en-US";
  recognition.continuous = false;
  recognition.interimResults = true;

  const baseText = box.value ? box.value.trim() + " " : "";

  recognition.onstart = function() {
    isLiveRecording = true;
    btn.classList.add("recording");
    statusEl.textContent = "🎙️ Listening live... Speak now (tap again to stop)";
  };

  recognition.onresult = function(event) {
    let transcript = "";
    for (let i = 0; i < event.results.length; i++) {
      transcript += event.results[i][0].transcript;
    }
    box.value = baseText + transcript;
  };

  recognition.onerror = function(e) {
    statusEl.textContent = "⚠️ Mic notice: " + e.error + " — make sure Microphone permission is Allowed in Chrome site settings.";
  };

  recognition.onend = function() {
    isLiveRecording = false;
    btn.classList.remove("recording");
    statusEl.textContent = "✅ Voice captured into review box! Edit if needed, then tap Send.";
  };

  recognition.start();
}

