// VOICE MODE 2: WHISPER AUDIO RECORDING -> LOCAL 64-CORE CLOUDTOP WHISPER
// ============================================================================
async function toggleWhisperRecording() {
  const btn = document.getElementById("whisperMicBtn");
  const label = document.getElementById("whisperBtnLabel");
  const statusEl = document.getElementById("voiceStatusText");

  if (isWhisperRecording && mediaRecorder) {
    mediaRecorder.stop();
    return;
  }

  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    audioChunks = [];
    mediaRecorder = new MediaRecorder(stream);

    mediaRecorder.ondataavailable = function(e) {
      if (e.data && e.data.size > 0) audioChunks.push(e.data);
    };

    mediaRecorder.onstart = function() {
      isWhisperRecording = true;
      btn.classList.add("recording");
      label.textContent = "Tap to Stop & Transcribe";
      statusEl.textContent = "🔴 Recording audio for Whisper... Tap Whisper button when done.";
    };

    mediaRecorder.onstop = async function() {
      isWhisperRecording = false;
      btn.classList.remove("recording");
      btn.classList.add("transcribing");
      label.textContent = "Transcribing...";
      statusEl.textContent = "⏳ Sending audio to local Whisper on your 64-core Cloudtop...";

      stream.getTracks().forEach(function(t) { t.stop(); });
      const blob = new Blob(audioChunks, { type: mediaRecorder.mimeType || "audio/webm" });
      const base64Audio = await blobToBase64(blob);

      try {
        const res = await apiCall({
          action: "upload_whisper_audio",
          audioBase64: base64Audio,
          mimeType: blob.type
        });
        if (res && res.jobId) {
          await pollWhisperJob(res.jobId);
        } else {
          statusEl.textContent = "⚠️ Failed to queue Whisper audio.";
        }
      } catch (err) {
        statusEl.textContent = "⚠️ Whisper error: " + err.message;
      } finally {
        btn.classList.remove("transcribing");
        label.textContent = "Whisper AI Mic";
      }
    };

    mediaRecorder.start();
  } catch (err) {
    statusEl.textContent = "⚠️ Microphone permission notice: " + err.message;
  }
}

async function pollWhisperJob(jobId) {
  const statusEl = document.getElementById("voiceStatusText");
  const box = document.getElementById("promptBox");
  for (let i = 0; i < 25; i++) {
    await new Promise(function(r) { setTimeout(r, 700); });
    const res = await apiCall({ action: "get_whisper_job", jobId: jobId });
    if (res && res.job) {
      if (res.job.status === "DONE") {
        const cur = box.value ? box.value.trim() + " " : "";
        box.value = cur + (res.job.text || "").trim();
        statusEl.textContent = "✅ Whisper transcription complete! Review text below before sending.";
        return;
      } else if (res.job.status === "ERROR") {
        statusEl.textContent = "⚠️ Whisper error: " + (res.job.error || "Unknown");
        return;
      }
    }
  }
  statusEl.textContent = "⚠️ Whisper transcription timed out.";
}

function blobToBase64(blob) {
  return new Promise(function(resolve, reject) {
    const reader = new FileReader();
    reader.onloadend = function() {
      const dataUrl = reader.result || "";
      const base64 = dataUrl.indexOf(",") !== -1 ? dataUrl.split(",")[1] : dataUrl;
      resolve(base64);
    };
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

function clearPrompt() {
  document.getElementById("promptBox").value = "";
  document.getElementById("voiceStatusText").textContent = "Cleared.";
}

