async function sendCommandToWorkspace() {
  const conv = getSelectedConvObject();
  const box = document.getElementById("promptBox");
  const statusEl = document.getElementById("voiceStatusText");
  const prompt = box.value.trim();

  if (!conv) {
    statusEl.textContent = "⚠️ Please select a conversation from the left slider first.";
    setSliderState("open");
    return;
  }
  if (!prompt) {
    statusEl.textContent = "⚠️ Please speak or type a command in the review box first.";
    box.focus();
    return;
  }

  const btn = document.getElementById("sendBtn");
  btn.disabled = true;
  btn.textContent = "⏳ Queuing command...";

  try {
    const res = await apiCall({
      action: "queue_command",
      conversationId: conv.id,
      conversationTitle: conv.title,
      workspace: conv.workspace,
      isNewConversation: !!conv.isNew,
      prompt: prompt
    });
    if (res && res.ok) {
      box.value = "";
      statusEl.textContent = '🚀 Sent to "' + conv.title + '"! Watching execution status...';
      await refreshState();
    } else {
      statusEl.textContent = "⚠️ Failed to send command.";
    }
  } finally {
    btn.disabled = false;
    renderSelectedStudio();
  }
}

async function cancelActiveConversation() {
  const conv = getSelectedConvObject();
  if (!conv || conv.isNew) return;
  const statusEl = document.getElementById("voiceStatusText");
  statusEl.textContent = '🛑 Sending Stop/Cancel signal to "' + conv.title + '"...';
  await apiCall({
    action: "cancel_conversation",
    conversationId: conv.id,
    conversationTitle: conv.title
  });
  setTimeout(refreshState, 1200);
}

