const staticData = $getWorkflowStaticData('global');
if (!staticData.workspaces) staticData.workspaces = [];
if (!staticData.conversations) staticData.conversations = [];
if (!staticData.commands) staticData.commands = [];
if (!staticData.whisperJobs) staticData.whisperJobs = {};
if (!staticData.cancelQueue) staticData.cancelQueue = [];
if (!staticData.lastBridgeHeartbeat) staticData.lastBridgeHeartbeat = 0;
if (!staticData.gcert) staticData.gcert = { valid: true, needsRenewal: false, label: '155h left', raw: 'LOAS2 valid' };

const body = $input.first().json.body || $input.first().json || {};
const action = body.action || '';
const APP_PIN = "082026";
const BRIDGE_SECRET = "jetski-bridge-sumantob-2026-secret-9941";

// Bridge endpoints (authenticated by bridgeSecret)
if (action.startsWith('bridge_')) {
  if (body.bridgeSecret !== BRIDGE_SECRET) {
    return [{ json: { apiResponse: { error: 'INVALID_BRIDGE_SECRET' } } }];
  }

  staticData.lastBridgeHeartbeat = Date.now();

  if (action === 'bridge_sync') {
    if (Array.isArray(body.workspaces)) staticData.workspaces = body.workspaces;
    if (Array.isArray(body.conversations)) staticData.conversations = body.conversations;
    if (body.gcert) staticData.gcert = body.gcert;

    const pendingWhisper = [];
    for (const [jid, job] of Object.entries(staticData.whisperJobs)) {
      if (job.status === 'PENDING') {
        job.status = 'TRANSCRIBING';
        pendingWhisper.push(job);
      }
    }

    const pendingCommands = [];
    for (const cmd of staticData.commands) {
      if (cmd.status === 'QUEUED') {
        cmd.status = 'RUNNING';
        pendingCommands.push(cmd);
      }
    }

    const cancels = staticData.cancelQueue.splice(0, staticData.cancelQueue.length);

    return [{
      json: {
        apiResponse: {
          ok: true,
          pendingWhisper,
          pendingCommands,
          cancels
        }
      }
    }];
  }

  if (action === 'bridge_whisper_result') {
    const jid = body.jobId;
    if (jid && staticData.whisperJobs[jid]) {
      staticData.whisperJobs[jid].status = body.error ? 'ERROR' : 'DONE';
      staticData.whisperJobs[jid].text = body.text || '';
      staticData.whisperJobs[jid].error = body.error || '';
      delete staticData.whisperJobs[jid].audioBase64;
    }
    return [{ json: { apiResponse: { ok: true } } }];
  }

  if (action === 'bridge_command_update') {
    const cid = body.commandId;
    const found = staticData.commands.find(c => c.id === cid);
    if (found) {
      if (body.status) found.status = body.status;
      if (body.reply !== undefined) found.reply = body.reply;
      if (body.newConversationId) found.conversationId = body.newConversationId;
    }
    return [{ json: { apiResponse: { ok: true } } }];
  }
}

